"""Bind a normal locked UI build to its clean source inputs and generated bytes."""

from __future__ import annotations

import hashlib
import json
import os
import subprocess
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[3]
MARKER = ".usage-checkpoint-build.json"


def _git(root: Path, *arguments: str) -> str:
    return subprocess.check_output(["git", *arguments], cwd=root, text=True).strip()


def source_snapshot(root: Path) -> dict[str, Any]:
    """Require clean compiled inputs; test-only commits need not trigger a rebuild."""
    assert os.environ.get("COGNIS_APPLE_BUNDLE") != "1", (
        "COGNIS_APPLE_BUNDLE=1 is unsupported: qualification requires canonical ui/build"
    )
    ui = root / "ui"
    for name in (".env", ".env.local", ".env.production", ".env.production.local"):
        assert not (ui / name).exists(), f"Do not build with an inherited {name}"
    assert not any(name.startswith(("PUBLIC_", "VITE_")) for name in os.environ), (
        "Use the qualification's default relative API configuration"
    )
    status = _git(root, "status", "--porcelain", "--untracked-files=all", "--", "ui")
    assert all("ui/e2e/" in line for line in status.splitlines()), (
        "Compiled UI sources must match their committed revision"
    )
    names = _git(root, "ls-files", "--", "ui").splitlines()
    sources = {
        name: hashlib.sha256((root / name).read_bytes()).hexdigest()
        for name in names
        if not name.startswith("ui/e2e/")
    }
    assert "ui/package-lock.json" in sources and "ui/src/app.html" in sources
    return {
        "revision": _git(root, "rev-parse", "HEAD"),
        "tree": _git(root, "rev-parse", "HEAD^{tree}"),
        "ui_tree": _git(root, "rev-parse", "HEAD:ui"),
        "source_hashes": sources,
    }


def _outputs(build: Path) -> dict[str, str]:
    assert (build / "index.html").is_file(), "The actual application build is required"
    return {
        str(path.relative_to(build)): hashlib.sha256(path.read_bytes()).hexdigest()
        for path in sorted(build.rglob("*"))
        if path.is_file() and path.name != MARKER
    }


def _record(root: Path, build: Path, before: dict[str, Any]) -> dict[str, Any]:
    after = source_snapshot(root)
    assert before == after, "Sources changed while the application was building"
    manifest = {
        "version": 1,
        "command": ["npm", "run", "build"],
        "source": before,
        "outputs": _outputs(build),
    }
    (build / MARKER).write_text(json.dumps(manifest, indent=2, sort_keys=True))
    return manifest


def verify_build(root: Path, build: Path | None = None) -> dict[str, Any]:
    """Reject missing, stale-source and modified-output provenance before startup."""
    build = build if build is not None else root / "ui/build"
    manifest = json.loads((build / MARKER).read_text())
    assert manifest["version"] == 1 and manifest["command"] == ["npm", "run", "build"]
    current = source_snapshot(root)
    assert manifest["source"]["source_hashes"] == current["source_hashes"], (
        "Build does not match the committed UI inputs; rebuild under the shared lock"
    )
    assert manifest["outputs"] == _outputs(build), "Build output changed after qualification"
    return manifest


def main() -> None:
    """Run under make validate, before starting any service against this build."""
    before = source_snapshot(ROOT)
    subprocess.run(["npm", "run", "build"], cwd=ROOT / "ui", check=True)
    manifest = _record(ROOT, ROOT / "ui/build", before)
    print(json.dumps({key: value for key, value in manifest.items() if key != "outputs"}, indent=2))


if __name__ == "__main__":
    main()
